pub(super) fn kind(scope: Scope) -> Kind {
    match scope {
        Scope::Document => Kind::Document,
        Scope::Page(_) | Scope::Master(_) => Kind::Page,
        Scope::Style(_) => Kind::Style,
        _ => Kind::Shape,
    }
}
static INDEX: LazyLock<BTreeMap<(Kind, String), usize>> =
    LazyLock::new(|| CELLS.iter().enumerate().map(|(i, c)| ((c.kind, c.cell.name.to_ascii_lowercase()), i)).collect());
pub(super) fn cell(scope: Scope, name: &str) -> Option<&'static Cell> {
    let index = INDEX.get(&(kind(scope), name.to_ascii_lowercase()))?;
    CELLS.get(*index).map(|c| &c.cell)
}
